def count_vowels(s: str) -> int:
    vowels = set("aeiouAEIOU")
    count = 0
    n = len(s)
    for i in range(n):
        if s[i] in vowels:
            continue
        if i == 0:
            if n > 1 and s[i + 1] in vowels:
                count += 1
        elif i == n - 1:
            if n > 1 and s[i - 1] in vowels:
                count += 1
        else:
            if s[i - 1] in vowels or s[i + 1] in vowels:
                count += 1
    return count
